"""Safe Markdown reports whose labels and links are generated by the host."""

import html
import json
import re
import unicodedata
from urllib.parse import quote, urlsplit

from .assessments import qualifications


def authored(value):
    """Render authored material as inert readable text, never Markdown syntax."""
    if not isinstance(value, str):
        value = json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True)
    value = "".join((f"\\u{ord(char):04x}" if ord(char) <= 0xffff else f"\\U{ord(char):08x}")
                    if unicodedata.category(char).startswith("C") or char in "\u2028\u2029" else char
                    for char in value)
    value = html.escape(value, quote=True)
    value = re.sub(r"(?i)https?://", lambda match: match.group(0).split(":", 1)[0] + "&#58;//", value)
    return re.sub(r"([\\`*_{}\[\]()#+>|~])", r"\\\1", value)


def _public_https(value):
    if not isinstance(value, str) or len(value) > 4096 or any(ord(char) < 32 for char in value):
        return None
    parsed = urlsplit(value)
    if parsed.scheme != "https" or not parsed.hostname or parsed.username or parsed.password:
        return None
    return value.replace(" ", "%20").replace("(", "%28").replace(")", "%29")


def _doi(value):
    if not isinstance(value, str):
        return None
    clean = re.sub(r"^https?://(?:dx\.)?doi\.org/", "", value.strip().lower()).rstrip(".,;)")
    return clean if re.fullmatch(r"10\.[0-9]{4,9}/[^\s<>\"]{1,256}", clean) else None


def _citation_state(report):
    sources, source_by_id, claim_sources = [], {}, {}
    for snapshot in report["claim_snapshots"]:
        identifiers = []
        for source in snapshot["sources"]:
            identifier = source["id"]
            if identifier not in source_by_id:
                source_by_id[identifier] = len(sources) + 1
                sources.append(source)
        evidence_by_source = {}
        for evidence in snapshot.get("evidence", []):
            evidence_by_source.setdefault(evidence.get("source_id"), []).append(_locator_suffix(evidence.get("locator")))
        for source in snapshot["sources"]:
            suffixes = evidence_by_source.get(source["id"]) or [""]
            for suffix in suffixes:
                item = (source["id"], suffix)
                if item not in identifiers:
                    identifiers.append(item)
        claim_sources[snapshot["claim"]["id"]] = identifiers
    return sources, source_by_id, claim_sources


def _locator_suffix(locator):
    pointer = locator.get("pointer") if isinstance(locator, dict) else None
    if not isinstance(pointer, str):
        return ""
    match = re.fullmatch(r"/pages/([0-9]+)/text", pointer)
    if match:
        return f", p. {int(match.group(1)) + 1}"
    match = re.fullmatch(r"/sections/([0-9]+)/paragraphs/([0-9]+)/text", pointer)
    if match:
        return f", sec. {int(match.group(1)) + 1} para. {int(match.group(2)) + 1}"
    match = re.fullmatch(r"/abstract/([0-9]+)/text", pointer)
    if match:
        return f", abstract para. {int(match.group(1)) + 1}"
    return ""


def _labels(claim_ids, source_by_id, claim_sources):
    labels = []
    for claim_id in claim_ids:
        for source_id, suffix in claim_sources.get(claim_id, []):
            number = source_by_id[source_id]
            label = (number, suffix)
            if label not in labels:
                labels.append(label)
    return " ".join(f"[S{number}{suffix}]" for number, suffix in labels)


def _evidence_excerpt(evidence, source_by_id):
    source_id = evidence.get("source_id") if isinstance(evidence, dict) else None
    number = source_by_id.get(source_id)
    suffix = _locator_suffix(evidence.get("locator")) if isinstance(evidence, dict) else ""
    label = f"[S{number}{suffix}]" if number is not None else "[source unavailable]"
    value = evidence.get("text") if isinstance(evidence, dict) else None
    if not isinstance(value, str):
        value = evidence.get("value") if isinstance(evidence, dict) else None
    if not isinstance(value, str):
        value = json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True)
    truncated = len(value) > 4000
    value = value[:4000]
    if truncated:
        value += " [evidence excerpt truncated; complete selection retained in the host ledger]"
    return label, value


def _qualification_text(source):
    value = qualifications(source)
    availability = authored(value.get("text_availability", "unknown"))
    limitations = value.get("limitations", [])
    rendered = "; ".join(authored(item) for item in limitations if isinstance(item, str))
    return f"Text availability: {availability}; limitations: {rendered or 'none recorded.'}"


def _identifier_lines(source, number, renderer_version):
    provenance = source.get("provenance", {})
    url = _public_https(provenance.get("url"))
    doi = _doi(provenance.get("doi"))
    pmid = provenance.get("pmid")
    pmcid = provenance.get("pmcid")
    label = f"[S{number}]({url})" if url else f"S{number}"
    pieces = [f"- {label} — {authored(source.get('title', 'Untitled source'))}"]
    identifiers = []
    if doi:
        identifiers.append(f"DOI: [{doi}](https://doi.org/{quote(doi, safe='/')})")
    if isinstance(pmid, str) and re.fullmatch(r"[1-9][0-9]{0,11}", pmid):
        identifiers.append(f"PMID: [{pmid}](https://pubmed.ncbi.nlm.nih.gov/{pmid}/)")
    if isinstance(pmcid, str) and re.fullmatch(r"PMC[0-9]{1,12}", pmcid):
        identifiers.append(f"PMCID: [{pmcid}](https://pmc.ncbi.nlm.nih.gov/articles/{pmcid}/)")
    if identifiers:
        pieces.append("  " + "; ".join(identifiers))
    qualification = (_qualification_text(source) if renderer_version == 2 else
                     authored(json.dumps(qualifications(source), ensure_ascii=False,
                                         allow_nan=False, sort_keys=True)))
    pieces.append("  Source/method qualifications: " + qualification)
    return pieces


def render_report(report):
    if report.get("renderer_version") in (4,5):
        from .rendering_review import render_review_report
        from .design import render_design
        rendered = render_review_report(report).decode("utf-8")
        marker = "## 论断与证据审计\n"
        return rendered.replace(marker, render_design(report["research_design"], execution_note=report['renderer_version']==5) + marker, 1).encode("utf-8")
    renderer_version = report.get("renderer_version", 1)
    if renderer_version == 3:
        from .rendering_review import render_review_report
        return render_review_report(report)
    if renderer_version not in (1, 2):
        raise ValueError("Unsupported report renderer version")
    sources, source_by_id, claim_sources = _citation_state(report)
    snapshots = {item["claim"]["id"]: item for item in report["claim_snapshots"]}
    lines = ["# Research report", "",
        "> Structural acceptance is not scientific assurance, model termination, or efficacy/safety certification.", "",
        "Author-supplied title: " + authored(report["title"]), ""]
    for number, section in enumerate(report["sections"], 1):
        lines.extend([f"## Section {number}: {authored(section['heading'])}", "",
                      "Author-supplied heading: " + authored(section["heading"]), ""])
        for paragraph in section.get("paragraphs", []):
            label_text = _labels(paragraph["claim_ids"], source_by_id, claim_sources)
            lines.append(authored(paragraph["text"]) + (" " + label_text if label_text else ""))
            lines.append("")
        for claim_id in section["claim_ids"]:
            snapshot = snapshots[claim_id]
            claim, assessment = snapshot["claim"], snapshot["assessment"]
            status = assessment["status"] if assessment and snapshot["assessment_current"] else "unassessed"
            lines.extend([f"### Claim {authored(claim_id)}", "",
                f"Claim kind: {claim['kind']}", f"Assessment status: {status}",
                "Claim text (attributed content, not host proof): " + authored(claim["text"])])
            label_text = _labels([claim_id], source_by_id, claim_sources)
            if label_text:
                lines.append("Bound sources: " + label_text)
            if claim["kind"] != "observation":
                lines.append("This is an explicitly unestablished proposal or rejected claim, not an established finding.")
            if assessment:
                scope = "provisional semantic review" if assessment["provisional"] else "narrow literal-material verification only"
                lines.append("Assessment scope: " + scope)
            for evidence in snapshot["evidence"]:
                if renderer_version == 2:
                    evidence_label, evidence_text = _evidence_excerpt(evidence, source_by_id)
                    lines.extend([f"Selected evidence {evidence_label}:", "> " + authored(evidence_text)])
                else:
                    lines.append("Selected evidence: " + authored(json.dumps(
                        evidence, ensure_ascii=False, allow_nan=False, sort_keys=True)))
            for source in snapshot["sources"]:
                qualification = (_qualification_text(source) if renderer_version == 2 else
                                 authored(json.dumps(qualifications(source), ensure_ascii=False,
                                                     allow_nan=False, sort_keys=True)))
                lines.append("Source/method qualifications: " + qualification)
            lines.append("")
    lines.extend(["## Limitations", "", "Author-supplied limitations (not host-certified facts):"])
    if report["limitations"]:
        lines.extend("- " + authored(item) for item in report["limitations"])
    else:
        lines.append("- None supplied.")
    lines.extend(["", "## Sources", ""])
    if sources:
        for number, source in enumerate(sources, 1):
            lines.extend(_identifier_lines(source, number, renderer_version))
    else:
        lines.append("No source-backed citations were bound to this report.")
    return ("\n".join(lines).rstrip() + "\n").encode("utf-8")
